```turtle
@prefix fis:  <http://example.org/onto/securities#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .

<http://example.org/onto/securities> a owl:Ontology ;
  rdfs:label "Securities and Financial Instruments Ontology" ;
  rdfs:comment "An ontology of financial instruments, securities, derivatives, markets and market participants, modelled from a corpus on securities law/finance, bonds, equities, derivatives, funds and accounting classification (IAS 32 / IFRS 9)." .

#################################################################
# TOP-LEVEL: ASSET / FINANCIAL INSTRUMENT
#################################################################

fis:Asset a owl:Class ;
  rdfs:label "Asset" ;
  rdfs:comment "Any underlier or resource that may be referenced or owned, including financial instruments, commodities, currencies, indices, interest rates, mortgages and loans." .

fis:FinancialInstrument a owl:Class ;
  rdfs:subClassOf fis:Asset ;
  rdfs:label "Financial Instrument" ;
  rdfs:comment "A monetary contract between parties that can be created, traded, modified and settled (cash, ownership evidence, debt, equity, or derivative)." .

fis:CashInstrument a owl:Class ;
  rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Cash Instrument" ;
  rdfs:comment "A financial instrument whose value is determined directly by the markets, e.g. securities, loans and deposits." .

fis:Security a owl:Class ;
  rdfs:subClassOf fis:CashInstrument ;
  rdfs:label "Security" ;
  rdfs:comment "A tradable financial asset that entitles the holder to investment returns; may be certificated or non-certificated, bearer or registered." .

fis:Loan a owl:Class ; rdfs:subClassOf fis:CashInstrument ;
  rdfs:comment "A cash instrument requiring agreement between borrower and lender to transfer; not freely negotiable like a security." .

fis:Deposit a owl:Class ; rdfs:subClassOf fis:CashInstrument .

fis:RepurchaseAgreement a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:label "Repurchase Agreement" ;
  rdfs:comment "Combines the sale of an asset with its subsequent repurchase. The corpus states this instrument 'defies categorization' into the cash/derivative or security/loan matrix, so it is modelled directly under FinancialInstrument rather than under Security or Derivative." .

fis:Commodity a owl:Class ; rdfs:subClassOf fis:Asset .
fis:Currency a owl:Class ; rdfs:subClassOf fis:Asset .
fis:MarketIndex a owl:Class ; rdfs:subClassOf fis:Asset .
fis:InterestRateBenchmark a owl:Class ; rdfs:subClassOf fis:Asset .

fis:Mortgage a owl:Class ; rdfs:subClassOf fis:Asset .
fis:ResidentialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
fis:CommercialMortgage a owl:Class ; rdfs:subClassOf fis:Mortgage .
owl:AllDisjointClasses [ owl:members ( fis:ResidentialMortgage fis:CommercialMortgage ) ] .

fis:DebtObligation a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "A debt obligation (e.g. a bond or loan) used as collateral, e.g. for a CDO." .

fis:ConsumerLoan a owl:Class ; rdfs:subClassOf fis:Asset .
fis:AutoLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:StudentLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:CreditCardReceivable a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
fis:HomeEquityLoan a owl:Class ; rdfs:subClassOf fis:ConsumerLoan .
owl:AllDisjointClasses [ owl:members ( fis:AutoLoan fis:StudentLoan fis:CreditCardReceivable fis:HomeEquityLoan ) ] .

#################################################################
# ACCOUNTING CLASSIFICATION (IAS 32 / IFRS 9)
#################################################################

fis:FinancialAsset a owl:Class ; rdfs:subClassOf fis:Asset ;
  rdfs:comment "IAS 32: cash, an equity instrument of another entity, a contractual right to receive cash or another financial instrument, or a contractual right to exchange financial instruments under potentially favourable conditions." .

fis:FinancialLiability a owl:Class ;
  rdfs:comment "IAS 32: a contractual obligation to deliver cash or another financial asset, or to exchange financial instruments under potentially unfavourable conditions. NOTE: classification as liability vs equity follows contractual substance; a mandatorily redeemable preference share is classified as a FinancialLiability under IAS 32 even though it is commonly called 'preferred equity' in the market - a documented conflict between legal/market naming and accounting classification." .

fis:Equity a owl:Class ; rdfs:subClassOf fis:FinancialAsset ;
  rdfs:comment "All instruments and records acknowledging claims on the residual value of a corporation after the claims of all creditors have been met (ECB glossary); equivalent to IAS 32's 'equity instrument'." .

fis:CompoundFinancialInstrument a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "IAS 32: an instrument with both a liability component and an equity component, e.g. a convertible bond, whose components must be presented separately." .

fis:BusinessModel a owl:Class .
fis:HoldToCollect a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:HoldToCollectAndSell a owl:Class ; rdfs:subClassOf fis:BusinessModel .
fis:OtherBusinessModel a owl:Class ; rdfs:subClassOf fis:BusinessModel .
owl:AllDisjointClasses [ owl:members ( fis:HoldToCollect fis:HoldToCollectAndSell fis:OtherBusinessModel ) ] .

fis:CashFlowCharacteristic a owl:Class .
fis:SolelyPaymentsOfPrincipalAndInterest a owl:Class ; rdfs:subClassOf fis:CashFlowCharacteristic .
fis:OtherCashFlowCharacteristic a owl:Class ; rdfs:subClassOf fis:CashFlowCharacteristic .
owl:AllDisjointClasses [ owl:members ( fis:SolelyPaymentsOfPrincipalAndInterest fis:OtherCashFlowCharacteristic ) ] .

fis:MeasurementCategory a owl:Class .
fis:AmortisedCost a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughOCI a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
fis:FairValueThroughProfitOrLoss a owl:Class ; rdfs:subClassOf fis:MeasurementCategory .
owl:AllDisjointClasses [ owl:members ( fis:AmortisedCost fis:FairValueThroughOCI fis:FairValueThroughProfitOrLoss ) ] .

fis:AmortisedCostFinancialAsset a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:someValuesFrom fis:HoldToCollect ]
      [ a owl:Restriction ; owl:onProperty fis:hasCashFlowCharacteristic ; owl:someValuesFrom fis:SolelyPaymentsOfPrincipalAndInterest ]
  ) ] ;
  rdfs:comment "IFRS 9: measured at amortised cost if held to collect contractual cash flows and those cash flows are solely payments of principal and interest (SPPI)." .

fis:FVOCIFinancialAsset a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
      fis:FinancialAsset
      [ a owl:Restriction ; owl:onProperty fis:hasBusinessModel ; owl:someValuesFrom fis:HoldToCollectAndSell ]
      [ a owl:Restriction ; owl:onProperty fis:hasCashFlowCharacteristic ; owl:someValuesFrom fis:SolelyPaymentsOfPrincipalAndInterest ]
  ) ] ;
  rdfs:comment "IFRS 9: measured at fair value through OCI if held both to collect and sell, and cash flows are SPPI." .

#################################################################
# CLASSIFICATION HELPER (ENUMERATION) CLASSES
#################################################################

fis:InterestType a owl:Class .
fis:OwnershipInterest a owl:Class ; rdfs:subClassOf fis:InterestType .
fis:CreditorInterest a owl:Class ; rdfs:subClassOf fis:InterestType .
owl:AllDisjointClasses [ owl:members ( fis:OwnershipInterest fis:CreditorInterest ) ] .

fis:CouponType a owl:Class .
fis:FixedCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:FloatingCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:ZeroCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
fis:InflationLinkedCoupon a owl:Class ; rdfs:subClassOf fis:CouponType .
owl:AllDisjointClasses [ owl:members ( fis:FixedCoupon fis:FloatingCoupon fis:ZeroCoupon fis:InflationLinkedCoupon ) ] .

fis:ContractualRight a owl:Class .
fis:RightToBuy a owl:Class ; rdfs:subClassOf fis:ContractualRight .
fis:RightToSell a owl:Class ; rdfs:subClassOf fis:ContractualRight .
owl:AllDisjointClasses [ owl:members ( fis:RightToBuy fis:RightToSell ) ] .

fis:CertificateForm a owl:Class .
fis:BearerForm a owl:Class ; rdfs:subClassOf fis:CertificateForm .
fis:RegisteredForm a owl:Class ; rdfs:subClassOf fis:CertificateForm .
owl:AllDisjointClasses [ owl:members ( fis:BearerForm fis:RegisteredForm ) ] .

fis:CustodyForm a owl:Class .
fis:CertificatedForm a owl:Class ; rdfs:subClassOf fis:CustodyForm .
fis:NonCertificatedForm a owl:Class ; rdfs:subClassOf fis:CustodyForm ;
  rdfs:label "Non-certificated Form" ; rdfs:comment "Book-entry / dematerialised form." .
owl:AllDisjointClasses [ owl:members ( fis:CertificatedForm fis:NonCertificatedForm ) ] .

fis:DivisibilityType a owl:Class .
fis:Divided a owl:Class ; rdfs:subClassOf fis:DivisibilityType .
fis:Undivided a owl:Class ; rdfs:subClassOf fis:DivisibilityType .
owl:AllDisjointClasses [ owl:members ( fis:Divided fis:Undivided ) ] .

fis:ExerciseStyle a owl:Class .
fis:AmericanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
fis:EuropeanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
fis:BermudanStyle a owl:Class ; rdfs:subClassOf fis:ExerciseStyle .
owl:AllDisjointClasses [ owl:members ( fis:AmericanStyle fis:EuropeanStyle fis:BermudanStyle ) ] .

fis:TermCategory a owl:Class .
fis:ShortTerm a owl:Class ; rdfs:subClassOf fis:TermCategory .
fis:MediumTerm a owl:Class ; rdfs:subClassOf fis:TermCategory .
fis:LongTerm a owl:Class ; rdfs:subClassOf fis:TermCategory .
fis:Perpetual a owl:Class ; rdfs:subClassOf fis:TermCategory .
owl:AllDisjointClasses [ owl:members ( fis:ShortTerm fis:MediumTerm fis:LongTerm fis:Perpetual ) ] .

fis:BondFeature a owl:Class .
fis:CallFeature a owl:Class ; rdfs:subClassOf fis:BondFeature .
fis:PutFeature a owl:Class ; rdfs:subClassOf fis:BondFeature .
fis:ConversionFeature a owl:Class ; rdfs:subClassOf fis:BondFeature .
# Not asserted disjoint: a bond may be both callable and convertible.

fis:CreditRatingCategory a owl:Class .
fis:InvestmentGrade a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory .
fis:SpeculativeGrade a owl:Class ; rdfs:subClassOf fis:CreditRatingCategory ;
  rdfs:label "Speculative Grade" ; rdfs:comment "High-yield / junk grade." .
owl:AllDisjointClasses [ owl:members ( fis:InvestmentGrade fis:SpeculativeGrade ) ] .

fis:SeniorityRank a owl:Class .
fis:SeniorRank a owl:Class ; rdfs:subClassOf fis:SeniorityRank .
fis:SubordinatedRank a owl:Class ; rdfs:subClassOf fis:SeniorityRank .
owl:AllDisjointClasses [ owl:members ( fis:SeniorRank fis:SubordinatedRank ) ] .

#################################################################
# OBJECT PROPERTIES
#################################################################

fis:hasIssuer a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:Issuer ;
  rdfs:label "has issuer" .
fis:isIssuerOf a owl:ObjectProperty ; owl:inverseOf fis:hasIssuer ;
  rdfs:domain fis:Issuer ; rdfs:range fis:FinancialInstrument .

fis:hasUnderlying a owl:ObjectProperty ;
  rdfs:domain fis:Derivative ; rdfs:range fis:Asset ; rdfs:label "has underlying" .
fis:isUnderlyingOf a owl:ObjectProperty ; owl:inverseOf fis:hasUnderlying ;
  rdfs:domain fis:Asset ; rdfs:range fis:Derivative .

fis:hasHolder a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Investor .
fis:isHolderOf a owl:ObjectProperty ; owl:inverseOf fis:hasHolder ;
  rdfs:domain fis:Investor ; rdfs:range fis:Security .

fis:hasCollateral a owl:ObjectProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:Asset .
fis:isCollateralOf a owl:ObjectProperty ; owl:inverseOf fis:hasCollateral .

fis:hasInterestType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:InterestType .
fis:hasCouponType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:CouponType .
fis:confersRight a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:ContractualRight .
fis:hasCertificateForm a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:CertificateForm .
fis:hasCustodyForm a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:CustodyForm .
fis:hasDivisibilityType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:DivisibilityType .
fis:hasExerciseStyle a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range fis:ExerciseStyle .
fis:hasTermCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:TermCategory .
fis:hasBondFeature a owl:ObjectProperty ;
  rdfs:domain fis:Bond ; rdfs:range fis:BondFeature .
fis:hasCreditRatingCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:CreditRatingCategory .
fis:hasSeniorityRank a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range fis:SeniorityRank .
fis:hasConversionTarget a owl:ObjectProperty ;
  rdfs:domain fis:HybridSecurity ; rdfs:range fis:EquitySecurity .
fis:hasReferenceEntity a owl:ObjectProperty ;
  rdfs:domain fis:CreditDefaultSwap ; rdfs:range fis:Issuer .
fis:hasBusinessModel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:BusinessModel .
fis:hasCashFlowCharacteristic a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialAsset ; rdfs:range fis:CashFlowCharacteristic .
fis:hasMeasurementCategory a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:MeasurementCategory .
fis:hasComponent a owl:ObjectProperty ;
  rdfs:domain fis:FinancialInstrument ; rdfs:range fis:FinancialInstrument .
fis:isTradedOn a owl:ObjectProperty ;
  rdfs:domain fis:Security ; rdfs:range fis:Market .

#################################################################
# DATATYPE PROPERTIES
#################################################################

fis:hasFaceValue a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Security ; rdfs:range xsd:decimal ;
  rdfs:label "has face value" ; rdfs:comment "Also known as par/nominal/principal value." .
fis:hasCouponRate a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .
fis:hasMaturityDate a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:DebtSecurity ; rdfs:range xsd:date .
fis:hasStrikePrice a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain fis:Option ; rdfs:range xsd:decimal .
fis:hasYield a owl:DatatypeProperty ;
  rdfs:domain fis:Bond ; rdfs:range xsd:decimal .
fis:hasConversionRatio a owl:DatatypeProperty ;
  rdfs:domain fis:ConvertibleSecurity ; rdfs:range xsd:decimal .
fis:hasConversionPrice a owl:DatatypeProperty ;
  rdfs:domain fis:ConvertibleSecurity ; rdfs:range xsd:decimal .
fis:hasNotionalAmount a owl:DatatypeProperty ;
  rdfs:domain fis:Derivative ; rdfs:range xsd:decimal .
fis:isTradable a owl:DatatypeProperty ; rdfs:domain fis:FinancialInstrument ; rdfs:range xsd:boolean .
fis:isFungible a owl:DatatypeProperty ; rdfs:domain fis:Security ; rdfs:range xsd:boolean .
fis:isStandardized a owl:DatatypeProperty ; rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .
fis:isExchangeTraded a owl:DatatypeProperty ; rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .
fis:isObligatory a owl:DatatypeProperty ; rdfs:domain fis:Derivative ; rdfs:range xsd:boolean .

#################################################################
# SECURITY DEFINITION
#################################################################

fis:Security owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:CashInstrument
    [ a owl:Restriction ; owl:onProperty fis:isTradable ; owl:hasValue true ]
) ] .

fis:FungibleSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue true ] ) ] ;
  rdfs:comment "All holdings of the security are treated identically and are interchangeable." .
fis:NonFungibleSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:isFungible ; owl:hasValue false ] ) ] .

fis:BearerSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:someValuesFrom fis:BearerForm ] ) ] ;
  rdfs:comment "Entitles the holder to rights under the security merely by holding it; transferred by delivery." .
fis:RegisteredSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasCertificateForm ; owl:someValuesFrom fis:RegisteredForm ] ) ] ;
  rdfs:comment "Entitles the holder to rights only if they appear on a security register." .

fis:CertificatedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasCustodyForm ; owl:someValuesFrom fis:CertificatedForm ] ) ] .
fis:NonCertificatedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasCustodyForm ; owl:someValuesFrom fis:NonCertificatedForm ] ) ] ;
  rdfs:label "Non-certificated Security" ; rdfs:comment "Also called book-entry or dematerialised security." .

fis:DividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasDivisibilityType ; owl:someValuesFrom fis:Divided ] ) ] ;
  rdfs:comment "Each instrument constitutes a separate asset/debt legally distinct from each other security in the issue." .
fis:UndividedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasDivisibilityType ; owl:someValuesFrom fis:Undivided ] ) ] ;
  rdfs:comment "The entire issue makes up one asset; each security is a fractional part of the undivided whole." .

#################################################################
# DEBT SECURITY / EQUITY SECURITY TOP DEFINITIONS
#################################################################

fis:DebtSecurity a owl:Class ;
  rdfs:label "Debt Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasInterestType ; owl:someValuesFrom fis:CreditorInterest ]
  ) ] ;
  rdfs:comment "The holder is entitled to payment of principal and interest; the issuer is the debtor, the holder the creditor." .

fis:EquitySecurity a owl:Class ;
  rdfs:subClassOf fis:Equity ;
  rdfs:label "Equity Security" ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Security [ a owl:Restriction ; owl:onProperty fis:hasInterestType ; owl:someValuesFrom fis:OwnershipInterest ]
  ) ] ;
  rdfs:comment "A share of equity interest in an entity; not entitled to any fixed payment, shares only in the residual interest after creditors are paid." .
fis:EquitySecurity rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ;
   owl:someValuesFrom [ a owl:Class ; owl:unionOf ( fis:FairValueThroughOCI fis:FairValueThroughProfitOrLoss ) ] ] .

fis:HybridSecurity a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Combines some characteristics of both debt and equity securities. NOTE: this conflicts with the US (SEC) categorisation, which presents Debt, Equity and Derivatives as three mutually exclusive categories of securities; the corpus explicitly introduces hybrids (preferred stock, convertibles, warrants) as a further family, so HybridSecurity is not asserted disjoint from DebtSecurity/EquitySecurity." .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity ) ] .

#################################################################
# BOND / MONEY MARKET INSTRUMENT
#################################################################

fis:Bond a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A security under which the issuer owes the holder a debt and must provide cash flow (coupon and/or principal repayment) over a specified term; typically has a term of one year or more." .

fis:MoneyMarketInstrument a owl:Class ; rdfs:subClassOf fis:DebtSecurity ;
  rdfs:comment "A short-term debt instrument, generally with an original maturity of one year or less; sometimes called 'near cash'." .
owl:AllDisjointClasses [ owl:members ( fis:Bond fis:MoneyMarketInstrument ) ] .

fis:CertificateOfDeposit a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "A time deposit, commonly offered by banks, thrift institutions and credit unions; negotiable CDs trade in bearer form." .
fis:CommercialPaper a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  rdfs:comment "An unsecured promissory note with a fixed maturity of usually less than 270 days." .
fis:EuroCommercialPaper a owl:Class ; rdfs:subClassOf fis:CommercialPaper .
fis:TreasuryBill a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
     fis:MoneyMarketInstrument [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:comment "Zero-coupon short-term debt obligation of a national government, maturing in one year or less." .
fis:BankersAcceptance a owl:Class ; rdfs:subClassOf fis:MoneyMarketInstrument .

#--- Bond classification by issuer ---

fis:GovernmentBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SovereignGovernment ] ) ] ;
  rdfs:label "Government Bond" ; rdfs:comment "Also called treasury bond or sovereign bond; in the UK called a gilt." .
fis:SupranationalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:SupranationalOrganization ] ) ] .
fis:MunicipalBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Municipality ] ) ] ;
  rdfs:comment "Sub-sovereign government bond, issued by a local authority or subdivision; a 'muni' in the US." .
fis:CorporateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "CONFLICT NOTE: one passage states the term 'corporate bond' sometimes also encompasses bonds issued by supranational organisations, though strictly it applies only to corporations; here CorporateBond is modelled strictly (issuer is a Corporation), following the majority/strict definition." .

fis:ConventionalGilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:IndexLinkedGilt a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:TreasuryNote a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:TreasuryInflationProtectedSecurity a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:WarBond a owl:Class ; rdfs:subClassOf fis:GovernmentBond .
fis:ClimateBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Issued by a government or corporate entity to finance climate mitigation/adaptation projects." .

fis:GeneralObligationBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
fis:RevenueBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond ;
  rdfs:comment "Repaid solely from revenues of a specified revenue-generating entity; typically non-recourse." .
fis:AssessmentBond a owl:Class ; rdfs:subClassOf fis:GeneralObligationBond .
fis:BuildAmericaBond a owl:Class ; rdfs:subClassOf fis:MunicipalBond .
owl:AllDisjointClasses [ owl:members ( fis:GeneralObligationBond fis:RevenueBond ) ] .

fis:InvestmentGradeBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:InvestmentGrade ] ) ] .
fis:HighYieldBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCreditRatingCategory ; owl:someValuesFrom fis:SpeculativeGrade ] ) ] ;
  rdfs:label "High Yield Bond" ; rdfs:comment "Also called junk bond." .

fis:SeniorBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:someValuesFrom fis:SeniorRank ] ) ] .
fis:SubordinatedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasSeniorityRank ; owl:someValuesFrom fis:SubordinatedRank ] ) ] .

fis:SocialImpactBond a owl:Class ; rdfs:subClassOf fis:Bond .
fis:CoveredBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Backed by cash flows from mortgages or public-sector assets, which remain on the issuer's balance sheet - unlike an AssetBackedSecurity." .

#--- Bond classification by coupon type ---

fis:FixedRateBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FixedCoupon ] ) ] .
fis:FloatingRateNote a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:FloatingCoupon ] ) ] ;
  rdfs:label "Floating Rate Note" ; rdfs:comment "Coupon varies with a money-market reference rate such as SOFR (formerly LIBOR)." .
fis:ZeroCouponBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:ZeroCoupon ] ) ] ;
  rdfs:comment "Pays no regular interest; sold at a deep discount to par, redeemed at full principal at maturity." .
fis:InflationIndexedBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCouponType ; owl:someValuesFrom fis:InflationLinkedCoupon ] ) ] ;
  rdfs:comment "Principal and/or interest indexed to a consumer price index, e.g. TIPS, I-bonds, index-linked gilts." .
fis:StripBond a owl:Class ; rdfs:subClassOf fis:ZeroCouponBond ;
  rdfs:comment "Created by separating ('stripping') coupons from the principal of a fixed rate bond." .

#--- Bond classification by embedded feature ---

fis:CallableBond a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasBondFeature ; owl:someValuesFrom fis:CallFeature ] ) ] .
fis:PutableBond a owl:Class ;
  rdfs:label "Putable Bond" ; rdfs:comment "Also called a retractable bond." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasBondFeature ; owl:someValuesFrom fis:PutFeature ] ) ] .
fis:BulletBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "A straight bond that is neither callable nor putable." .

#--- Bond classification by certificate / custody form ---

fis:BearerBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:BearerSecurity .
fis:RegisteredBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:RegisteredSecurity .
fis:BookEntryBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:NonCertificatedSecurity .

#--- Bond classification by term ---

fis:ShortTermBond a owl:Class ; owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:ShortTerm ] ) ] .
fis:MediumTermBond a owl:Class ; owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:MediumTerm ] ) ] .
fis:LongTermBond a owl:Class ; owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:LongTerm ] ) ] .
fis:PerpetualBond a owl:Class ; owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
   fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasTermCategory ; owl:someValuesFrom fis:Perpetual ] ) ] ;
  rdfs:comment "Also called a perpetuity or 'perp'; has no maturity date." .
fis:Methuselah a owl:Class ; rdfs:subClassOf fis:LongTermBond ;
  rdfs:comment "A bond with a maturity of 50 years or longer." .
fis:SerialBond a owl:Class ; rdfs:subClassOf fis:Bond ;
  rdfs:comment "Matures in installments over a period of time." .

#################################################################
# ASSET-BACKED / MORTGAGE-BACKED SECURITIES
#################################################################

fis:AssetBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Asset ] ) ] ;
  rdfs:comment "Bonds whose interest and principal payments are backed by underlying cash flows from a pool of other assets. NOTE: the corpus uses 'asset-backed security' both as an umbrella term (covering MBS and CDO) and, more narrowly, as a term for securities backed specifically by consumer loans; both senses are modelled, with ConsumerLoanBackedSecurity representing the narrow sense." .

fis:MortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:Mortgage ] ) ] .
fis:ResidentialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MortgageBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ResidentialMortgage ] ) ] .
fis:CommercialMortgageBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:MortgageBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CommercialMortgage ] ) ] .
fis:PassThroughSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "Allocates cash flows from the underlying pool to holders pro rata; the basic/vanilla MBS." .
fis:CollateralizedMortgageObligation a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity ;
  rdfs:comment "A 'pay-through bond' divided into classes/tranches with different maturities and payment priorities." .
fis:StrippedMortgageBackedSecurity a owl:Class ; rdfs:subClassOf fis:MortgageBackedSecurity .
fis:InterestOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
fis:PrincipalOnlyStrip a owl:Class ; rdfs:subClassOf fis:StrippedMortgageBackedSecurity .
owl:AllDisjointClasses [ owl:members ( fis:InterestOnlyStrip fis:PrincipalOnlyStrip ) ] .

fis:CollateralizedDebtObligation a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:comment "A structured asset-backed security sliced into tranches catching cash flow in order of seniority." .

fis:ConsumerLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:AssetBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:ConsumerLoan ] ) ] ;
  rdfs:comment "The narrow sense of 'ABS': backed by consumer loans such as auto loans, credit cards and student loans." .
fis:HomeEquityLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:ConsumerLoanBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:HomeEquityLoan ] ) ] .
fis:AutoLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:ConsumerLoanBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:AutoLoan ] ) ] .
fis:CreditCardReceivableBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:ConsumerLoanBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:CreditCardReceivable ] ) ] .
fis:StudentLoanBackedSecurity a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:ConsumerLoanBackedSecurity [ a owl:Restriction ; owl:onProperty fis:hasCollateral ; owl:someValuesFrom fis:StudentLoan ] ) ] .

#################################################################
# EQUITY SECURITY HIERARCHY
#################################################################

fis:Stock a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:EquitySecurity [ a owl:Restriction ; owl:onProperty fis:hasIssuer ; owl:someValuesFrom fis:Corporation ] ) ] ;
  rdfs:comment "Capital stock of a corporation, divided into shares; the most specific, corporate form of equity security (equity securities more broadly also cover trusts and partnerships)." .

fis:CommonStock a owl:Class ; rdfs:subClassOf fis:Stock ;
  rdfs:label "Common Stock" ; rdfs:comment "Also called ordinary share/voting share; carries voting rights, lowest priority on dividends and liquidation." .
fis:PreferredStock a owl:Class ; rdfs:subClassOf fis:Stock, fis:HybridSecurity ;
  rdfs:label "Preferred Stock" ;
  rdfs:comment "Also called preference share(s); senior to common stock but subordinate to bonds; generally considered a hybrid instrument. CONFLICT NOTE: under IAS 32, a mandatorily redeemable preference share is reclassified as a FinancialLiability rather than equity, despite being called a 'share'." .
owl:AllDisjointClasses [ owl:members ( fis:CommonStock fis:PreferredStock ) ] .

fis:CumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:comment "Unpaid dividends accumulate as dividends in arrears." .
fis:NonCumulativePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock ;
  rdfs:label "Non-cumulative Preferred Stock" ; rdfs:comment "Also called 'straight' preferred; passed dividends are lost." .
owl:AllDisjointClasses [ owl:members ( fis:CumulativePreferredStock fis:NonCumulativePreferredStock ) ] .
fis:CallablePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock .
fis:ConvertiblePreferredStock a owl:Class ; rdfs:subClassOf fis:PreferredStock, fis:ConvertibleSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:PreferredStock [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:CommonStock ] ) ] .

fis:DepositaryReceipt a owl:Class ; rdfs:subClassOf fis:EquitySecurity ;
  rdfs:comment "A negotiable instrument issued by a bank representing a foreign company's publicly traded securities." .
fis:AmericanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:EuropeanDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
fis:GlobalDepositaryReceipt a owl:Class ; rdfs:subClassOf fis:DepositaryReceipt .
owl:AllDisjointClasses [ owl:members ( fis:AmericanDepositaryReceipt fis:EuropeanDepositaryReceipt fis:GlobalDepositaryReceipt ) ] .

#################################################################
# HYBRID SECURITIES
#################################################################

fis:ConvertibleSecurity a owl:Class ; rdfs:subClassOf fis:HybridSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:HybridSecurity [ a owl:Restriction ; owl:onProperty fis:hasConversionTarget ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:comment "A bond or preferred stock convertible, at the holder's election, into the issuer's common shares." .

fis:ConvertibleBond a owl:Class ; rdfs:subClassOf fis:Bond, fis:ConvertibleSecurity ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Bond [ a owl:Restriction ; owl:onProperty fis:hasBondFeature ; owl:someValuesFrom fis:ConversionFeature ] ) ] ;
  rdfs:comment "Also treated as a CompoundFinancialInstrument under IAS 32: a liability component (coupon/principal) plus an equity component (conversion option), presented separately." ;
  rdfs:subClassOf fis:CompoundFinancialInstrument .
fis:MandatoryConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Forces the holder to convert into shares at maturity." .
fis:PackagedConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "A straight bond and a call option/warrant wrapped together, tradeable as separate legs." .
fis:ContingentConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:label "Contingent Convertible Bond" ; rdfs:comment "Also called CoCo; converts automatically if a pre-specified trigger event occurs." .
fis:SyntheticConvertibleBond a owl:Class ; rdfs:subClassOf fis:ConvertibleBond ;
  rdfs:comment "Issued by a third party (e.g. an investment bank) to replicate a convertible payoff on a specific underlying equity; settled in cash rather than shares." .
fis:ConvertibleNote a owl:Class ; rdfs:subClassOf fis:ConvertibleSecurity ;
  rdfs:comment "A frequent vehicle for seed investing in startups: debt that converts to equity in a future investing round." .

fis:Warrant a owl:Class ; rdfs:subClassOf fis:HybridSecurity, fis:OptionProduct ;
  rdfs:label "Warrant" ; rdfs:comment "Also called equity warrant." ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:HybridSecurity
    [ a owl:Restriction ; owl:onProperty fis:confersRight ; owl:someValuesFrom fis:RightToBuy ]
    [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ]
  ) ] .

#################################################################
# DERIVATIVES
#################################################################

fis:Derivative a owl:Class ; rdfs:subClassOf fis:FinancialInstrument ;
  rdfs:comment "A contract whose value depends on the performance of an underlier (commodity, financial instrument, index, currency, interest rate, or an event such as default); defined by an underlier, a future act, a price and a future date." ;
  rdfs:subClassOf [ a owl:Restriction ; owl:onProperty fis:hasMeasurementCategory ; owl:someValuesFrom fis:FairValueThroughProfitOrLoss ] .

owl:AllDisjointClasses [ owl:members ( fis:DebtSecurity fis:EquitySecurity fis:Derivative ) ] .

fis:LockProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Obligates the contractual parties to the terms over the life of the contract (e.g. swaps, futures, forwards)." .
fis:OptionProduct a owl:Class ; rdfs:subClassOf fis:Derivative ;
  rdfs:comment "Provides the buyer the right, but not the obligation, to enter the contract under specified terms." .
owl:AllDisjointClasses [ owl:members ( fis:LockProduct fis:OptionProduct ) ] .

fis:Forward a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:LockProduct [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue false ] ) ] ;
  rdfs:comment "A non-standardized, tailored contract between two parties to buy/sell an asset at a specified future time at a price agreed today." .

fis:Future a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:LockProduct [ a owl:Restriction ; owl:onProperty fis:isStandardized ; owl:hasValue true ] ) ] ;
  rdfs:label "Future" ; rdfs:comment "A standardized contract written by a clearing house/exchange, unlike a forward." .

fis:Swap a owl:Class ; rdfs:subClassOf fis:LockProduct ;
  rdfs:comment "Two counterparties exchange cash flows ('legs') of one financial instrument for those of another, over a notional principal amount that is usually not exchanged." .
fis:InterestRateSwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CurrencySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CommoditySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:EquitySwap a owl:Class ; rdfs:subClassOf fis:Swap .
fis:CreditDefaultSwap a owl:Class ; rdfs:subClassOf fis:Swap, fis:CreditDerivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Swap [ a owl:Restriction ; owl:onProperty fis:hasReferenceEntity ; owl:someValuesFrom fis:Issuer ] ) ] ;
  rdfs:comment "The seller compensates the buyer in the event of default or other credit event affecting the reference entity's debt." .
owl:AllDisjointClasses [ owl:members ( fis:InterestRateSwap fis:CurrencySwap fis:CommoditySwap fis:EquitySwap fis:CreditDefaultSwap ) ] .

fis:Option a owl:Class ; rdfs:subClassOf fis:OptionProduct ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:OptionProduct [ a owl:Restriction ; owl:onProperty fis:hasStrikePrice ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "Gives the buyer the right, but not the obligation, to buy or sell an underlying asset at a specified strike price on or before a specified expiration date." .
fis:CallOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Option [ a owl:Restriction ; owl:onProperty fis:confersRight ; owl:someValuesFrom fis:RightToBuy ] ) ] .
fis:PutOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Option [ a owl:Restriction ; owl:onProperty fis:confersRight ; owl:someValuesFrom fis:RightToSell ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:CallOption fis:PutOption ) ] .

fis:AmericanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:AmericanStyle ] ) ] .
fis:EuropeanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:EuropeanStyle ] ) ] .
fis:BermudanOption a owl:Class ; rdfs:subClassOf fis:Option ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Option [ a owl:Restriction ; owl:onProperty fis:hasExerciseStyle ; owl:someValuesFrom fis:BermudanStyle ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:AmericanOption fis:EuropeanOption fis:BermudanOption ) ] .

fis:AsianOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "Payoff determined by the average underlying price over a preset period." .
fis:BarrierOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "The underlying price must pass a barrier before the option can be exercised." .
fis:BinaryOption a owl:Class ; rdfs:subClassOf fis:Option ;
  rdfs:comment "All-or-nothing profit profile." .
fis:ExoticOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:EmployeeStockOption a owl:Class ; rdfs:subClassOf fis:CallOption ;
  rdfs:comment "Awarded by a company to employees as incentive compensation." .
fis:ExchangeTradedOption a owl:Class ; rdfs:subClassOf fis:Option .
fis:OverTheCounterOption a owl:Class ; rdfs:subClassOf fis:Option .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedOption fis:OverTheCounterOption ) ] .

#--- derivative classification by underlying asset type ---

fis:EquityDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:EquitySecurity ] ) ] .
fis:InterestRateDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:InterestRateBenchmark ] ) ] .
fis:CurrencyDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Currency ] ) ] .
fis:CommodityDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Commodity ] ) ] .
fis:CreditDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:DebtObligation ] ) ] ;
  rdfs:comment "A contract that transfers credit risk from a protection buyer to a protection seller." .
owl:AllDisjointClasses [ owl:members ( fis:EquityDerivative fis:InterestRateDerivative fis:CurrencyDerivative fis:CommodityDerivative fis:CreditDerivative ) ] .

fis:StockDerivative a owl:Class ; rdfs:subClassOf fis:EquityDerivative ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:hasUnderlying ; owl:someValuesFrom fis:Stock ] ) ] ;
  rdfs:comment "Any financial instrument for which the underlying asset is the price of an equity." .
fis:StockOption a owl:Class ; rdfs:subClassOf fis:StockDerivative, fis:Option .
fis:StockFuture a owl:Class ; rdfs:subClassOf fis:StockDerivative, fis:Future .

fis:ExchangeTradedDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue true ] ) ] .
fis:OverTheCounterDerivative a owl:Class ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Derivative [ a owl:Restriction ; owl:onProperty fis:isExchangeTraded ; owl:hasValue false ] ) ] .
owl:AllDisjointClasses [ owl:members ( fis:ExchangeTradedDerivative fis:OverTheCounterDerivative ) ] .

#################################################################
# INVESTMENT FUNDS
#################################################################

fis:InvestmentFund a owl:Class ; rdfs:subClassOf fis:Security ;
  rdfs:comment "Pools money from many investors to purchase securities; the fund's shares represent a proportional interest in its portfolio." .

fis:MutualFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
fis:ExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:label "Exchange-Traded Fund" ; rdfs:comment "Trades continuously on an exchange at market prices that may differ from net asset value, unlike a mutual fund." .
fis:HedgeFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Pools investor money like a mutual fund but with fewer investor-protection regulations and more flexible/risky strategies." .
owl:AllDisjointClasses [ owl:members ( fis:MutualFund fis:ExchangeTradedFund fis:HedgeFund ) ] .

fis:OpenEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund ;
  rdfs:comment "Purchased from/sold to the issuer at net asset value; new investors may join at any time." .
fis:ClosedEndFund a owl:Class ; rdfs:subClassOf fis:MutualFund .
fis:UnitInvestmentTrust a owl:Class ; rdfs:subClassOf fis:MutualFund .
owl:AllDisjointClasses [ owl:members ( fis:OpenEndFund fis:ClosedEndFund fis:UnitInvestmentTrust ) ] .

fis:MoneyMarketFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Invests in liquid, short-term, low-risk money market instruments." .
fis:BondFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "Bond Fund" ; rdfs:comment "Also called income fund." .
fis:StockFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ; rdfs:label "Stock Fund" ; rdfs:comment "Also called equity fund." .
fis:HybridFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Blends equities and fixed income." .
owl:AllDisjointClasses [ owl:members ( fis:MoneyMarketFund fis:BondFund fis:StockFund fis:HybridFund ) ] .

fis:IndexFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund ;
  rdfs:comment "Passively managed fund tracking the performance of a market index." .
fis:ActivelyManagedFund a owl:Class ; rdfs:subClassOf fis:InvestmentFund .
owl:AllDisjointClasses [ owl:members ( fis:IndexFund fis:ActivelyManagedFund ) ] .

fis:InverseExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:comment "Designed to move opposite to its benchmark." .
fis:LeveragedExchangeTradedFund a owl:Class ; rdfs:subClassOf fis:ExchangeTradedFund ;
  rdfs:comment "Seeks to amplify the benchmark's daily return." .

#################################################################
# MARKETS
#################################################################

fis:Market a owl:Class ; rdfs:label "Market" .

fis:PrimaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for newly issued securities; the issuer receives the sale proceeds." .
fis:SecondaryMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for already-issued securities trading between investors." .
owl:AllDisjointClasses [ owl:members ( fis:PrimaryMarket fis:SecondaryMarket ) ] .

fis:CapitalMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for longer-term instruments (maturity beyond one year), e.g. bonds and equities." .
fis:MoneyMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Market for short-term funds/instruments with original maturities of one year or less." .
owl:AllDisjointClasses [ owl:members ( fis:CapitalMarket fis:MoneyMarket ) ] .

fis:BondMarket a owl:Class ; rdfs:subClassOf fis:CapitalMarket .
fis:EquityMarket a owl:Class ; rdfs:subClassOf fis:CapitalMarket ; rdfs:label "Equity Market" ; rdfs:comment "Also called the stock market." .
fis:DerivativesMarket a owl:Class ; rdfs:subClassOf fis:Market .

fis:Exchange a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "An organized and officially recognized market." .
fis:OverTheCounterMarket a owl:Class ; rdfs:subClassOf fis:Market ;
  rdfs:comment "Buyers and sellers deal directly with each other, off-exchange." .
owl:AllDisjointClasses [ owl:members ( fis:Exchange fis:OverTheCounterMarket ) ] .

fis:StockExchange a owl:Class ; rdfs:subClassOf fis:Exchange .
fis:DerivativesExchange a owl:Class ; rdfs:subClassOf fis:Exchange .
fis:FuturesExchange a owl:Class ; rdfs:subClassOf fis:DerivativesExchange .
fis:OptionsExchange a owl:Class ; rdfs:subClassOf fis:DerivativesExchange .

#################################################################
# MARKET PARTICIPANTS
#################################################################

fis:MarketParticipant a owl:Class .

fis:Issuer a owl:Class ; rdfs:subClassOf fis:MarketParticipant ;
  rdfs:comment "The entity which is obligated on a security or other financial instrument." .
fis:SovereignGovernment a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Municipality a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:Corporation a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:SupranationalOrganization a owl:Class ; rdfs:subClassOf fis:Issuer .
fis:GovernmentAgency a owl:Class ; rdfs:subClassOf fis:Issuer .
owl:AllDisjointClasses [ owl:members (
   fis:SovereignGovernment fis:Municipality fis:Corporation fis:SupranationalOrganization fis:GovernmentAgency
) ] .

fis:Investor a owl:Class ; rdfs:subClassOf fis:MarketParticipant .
fis:RetailInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "A member of the public investing personally, other than by way of business." .
fis:InstitutionalInvestor a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "Includes investment banks, insurance companies, pension funds and other managed funds." .
owl:AllDisjointClasses [ owl:members ( fis:RetailInvestor fis:InstitutionalInvestor ) ] .

fis:Shareholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Investor [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:EquitySecurity ] ) ] ;
  rdfs:label "Shareholder" ; rdfs:comment "Also called stockholder." .
fis:Bondholder a owl:Class ; rdfs:subClassOf fis:Investor ;
  owl:equivalentClass [ a owl:Class ; owl:intersectionOf (
    fis:Investor [ a owl:Restriction ; owl:onProperty fis:isHolderOf ; owl:someValuesFrom fis:DebtSecurity ] ) ] .
fis:BeneficialOwner a owl:Class ; rdfs:subClassOf fis:Investor ;
  rdfs:comment "The ultimate owner of a security held through a chain of intermediaries ('street name')." .

fis:Underwriter a owl:Class ; rdfs:subClassOf fis:MarketParticipant ;
  rdfs:comment "Buys an entire issue of securities from the issuer and resells it to investors." .
fis:BrokerDealer a owl:Class ; rdfs:subClassOf fis:MarketParticipant .
fis:ClearingHouse a owl:Class ; rdfs:subClassOf fis:MarketParticipant ;
  rdfs:comment "Acts as intermediary between buyer and seller of a futures or options contract and mitigates default risk." .
fis:Intermediary a owl:Class ; rdfs:subClassOf fis:MarketParticipant .
